//! Verify the live legacy iptables chains generated by the panel for one
//! concrete WireGuard UDP peer. A saved manifest alone cannot authorize it.
use super::wan::netifd_wan;
use std::{
    io,
    net::{IpAddr, SocketAddr},
};

const BYPASS: &str = "nfqws2_bypass";
const PARENTS: [&str; 2] = ["nfqws_pre", "nfqws_post"];
pub(super) fn grouped_output(rules: &str, ipv4: bool) -> io::Result<bool> {
    let mut entries = rules.lines().filter(|l| {
        l.split_ascii_whitespace()
            .any(|w| w.trim_matches('"') == "n2s-awg-setroute")
    });
    let mut present = false;
    while let Some(first) = entries.next() {
        let words = first
            .split_ascii_whitespace()
            .map(|s| s.trim_matches('"'))
            .collect::<Vec<_>>();
        let ["-A", "OUTPUT", "-m", "mark", "--mark", "0x0/0x20000000" | "0/0x20000000", "-m", "mark", "!", "--mark", "0x8000d500/0x8000ff80", matches @ .., "-m", "comment", "--comment", "n2s-awg-setroute", "-j", "MARK", "--set-xmark", mark] =
            words.as_slice()
        else {
            return Err(super::invalid(
                "не подтверждён классификатор транспорта AWG",
            ));
        };
        let owned = |name: &str| {
            name.strip_prefix(if ipv4 { "n2srt4_g" } else { "n2srt6_g" })
                .is_some_and(|t| t.len() == 22 && t.bytes().all(|b| b.is_ascii_hexdigit()))
        };
        let sets_valid = match matches {
            ["-m", "set", "--match-set", dest, "dst"] => owned(dest),
            ["-m", "set", "--match-set", src, "src", "-m", "set", "--match-set", dest, "dst"] => {
                owned(src) && owned(dest)
            }
            _ => false,
        };
        let val = mark
            .strip_prefix("0x")
            .and_then(|s| s.strip_suffix("/0x1ff00000"))
            .and_then(|s| u32::from_str_radix(s, 16).ok());
        let pair = entries
            .next()
            .map(|l| {
                l.split_ascii_whitespace()
                    .map(|w| w.trim_matches('"'))
                    .collect::<Vec<_>>()
            })
            .unwrap_or_default();
        if !sets_valid
            || !val.is_some_and(|n| (0x10000000..=0x18000000).contains(&n) && n & 0xfffff == 0)
            || pair.strip_suffix(&["ACCEPT"]) != Some(&words[..words.len() - 3])
        {
            return Err(super::invalid(
                "повреждены правила отдельного транспорта AWG",
            ));
        }
        present = true;
    }
    Ok(present)
}
pub(super) fn direct_socket_mark(
    ip: IpAddr,
    wan: &[String],
    tool: &str,
    grouped: bool,
    mut call: impl FnMut(&str, &[&str]) -> io::Result<String>,
) -> io::Result<Option<u32>> {
    let ip_text = ip.to_string();
    let family = if ip.is_ipv4() { "-4" } else { "-6" };
    let route = call(tool, &[family, "route", "get", &ip_text])?;
    let device = |r: &str| {
        r.split_ascii_whitespace()
            .skip_while(|t| *t != "dev")
            .nth(1)
            .unwrap_or_default()
            .to_owned()
    };
    let plain = device(&route);
    let mut mark = None;
    let mut actual = plain.clone();
    // Only an exact destination claimed by our packed policy can turn the
    // WAN check into a marked socket. Ordinary packets keep the AWG route.
    if plain
        .strip_prefix("awg")
        .is_some_and(|s| !s.is_empty() && s.bytes().all(|b| b.is_ascii_digit()))
    {
        // Entware iproute2 4.4 supports the selectors, but predates -Numeric.
        let lookup = call(tool, &["-o", family, "rule", "show"])?;
        let packed = lookup.lines().any(|l| {
            matches!(
                l.split_ascii_whitespace().collect::<Vec<_>>().as_slice(),
                [
                    "68:",
                    "from",
                    "all",
                    "fwmark",
                    "0/0x20000000" | "0x0/0x20000000",
                    "lookup",
                    "17842"
                ]
            )
        });
        let owned = packed
            && call(
                tool,
                &[
                    "-o", family, "route", "show", "table", "17842", "match", &ip_text,
                ],
            )?
            .lines()
            .any(|l| {
                let w: Vec<_> = l.split_ascii_whitespace().collect();
                let exact = w
                    .first()
                    .is_some_and(|p| p.trim_end_matches("/32").parse::<IpAddr>().ok() == Some(ip));
                exact
                    && w.windows(2).any(|p| p == ["dev", plain.as_str()])
                    && w.windows(2).any(|p| p == ["proto", "242"])
            });
        if owned {
            let path = call(
                tool,
                &[family, "route", "get", &ip_text, "mark", "0x20000000"],
            )?;
            actual = device(&path);
            mark = Some(crate::DIRECT_SOCKET_MARK);
        }
    }
    if grouped && !plain.starts_with("awg") {
        let path = call(
            tool,
            &[family, "route", "get", &ip_text, "mark", "0x20000000"],
        )?;
        if device(&path) != plain {
            return Err(super::invalid(
                "маркированный транспорт AWG изменяет выбранный WAN",
            ));
        }
        mark = Some(crate::DIRECT_SOCKET_MARK);
    }
    let valid = if wan.is_empty() {
        let interfaces = call("ubus", &["call", "network.interface", "dump"])?;
        netifd_wan(&interfaces, &actual, ip)?
    } else {
        wan.contains(&actual)
    };
    if !valid {
        return Err(super::invalid(
            "маршрут до Endpoint не использует настроенный WAN-интерфейс",
        ));
    }
    Ok(mark)
}
pub(super) fn verify(
    endpoint: SocketAddr,
    tables: io::Result<String>,
    nft: bool,
    mut call: impl FnMut(&str, &[&str]) -> io::Result<String>,
) -> io::Result<()> {
    let tables = match tables {
        Ok(t) => Some(t),
        Err(e) if e.kind() == io::ErrorKind::NotFound => None,
        Err(e) => return Err(e),
    };
    if nft && classified(&call("nft", &["list", "ruleset"])?) {
        return Err(super::invalid(
            "не подтверждено исключение транспорта VPN в правилах nftables",
        ));
    }
    let legacy = tables.as_deref().unwrap_or_default();
    // A stock fw4 router has nft and no legacy tables or xtables userspace.
    // On a mixed installation both backends must still be checked.
    if nft && legacy.trim().is_empty() {
        return Ok(());
    }
    let tool = if endpoint.is_ipv4() {
        "iptables"
    } else {
        "ip6tables"
    };
    let rules = match call(tool, &["-t", "mangle", "-S"]) {
        Ok(s) => s,
        Err(_) if !legacy.lines().any(|t| t == "mangle") => String::new(),
        Err(e) => return Err(e),
    };
    if classified(&rules) && (tables.is_none() || !protects(&rules, endpoint)) {
        return Err(super::invalid("для VPN Endpoint нет подтверждённых входящего и исходящего исключений. Примените списки NFQUEUE Bypass"));
    }
    for table in legacy.lines().filter(|t| *t != "mangle") {
        if !matches!(table, "filter" | "nat" | "raw" | "security")
            || classified(&call(tool, &["-t", table, "-S"])?)
        {
            return Err(super::invalid("обнаружен дополнительный классификатор без подтверждённого исключения транспорта VPN"));
        }
    }
    Ok(())
}
pub(super) fn classified(s: &str) -> bool {
    s.contains("NFQUEUE")
        || s.contains("NFQWS")
        || s.contains("nfqws_")
        || s.contains("AWG2_")
        || s.split_ascii_whitespace()
            .any(|v| v == "queue" || v == "QUEUE")
}
fn exact(tokens: &[&str], endpoint: SocketAddr, incoming: bool) -> bool {
    let address = if incoming { "-s" } else { "-d" };
    let port = if incoming { "--sport" } else { "--dport" };
    let mut host = false;
    let mut protocol = false;
    let mut number = false;
    let mut pairs = tokens.chunks_exact(2);
    if !pairs.remainder().is_empty() {
        return false;
    }
    pairs.all(|v| match v {
        ["-p", "udp"] if !protocol => {
            protocol = true;
            true
        }
        ["-m", "udp"] => true,
        [flag, value] if *flag == address && !host => {
            let (ip, mask) = value.split_once('/').unwrap_or((value, ""));
            host = ip.parse::<IpAddr>() == Ok(endpoint.ip())
                && (mask.is_empty() || mask == if endpoint.is_ipv4() { "32" } else { "128" });
            host
        }
        [flag, value] if *flag == port && !number => {
            number = value.parse::<u16>() == Ok(endpoint.port());
            number
        }
        _ => false,
    }) && host
        && protocol
        && number
}
pub(super) fn protects(rules: &str, ep: SocketAddr) -> bool {
    if rules.contains("AWG2_") {
        return false;
    }
    let mut declared = [false; 2];
    let mut jumps = [None; 2];
    let mut outgoing = false;
    let mut incoming = false;
    for line in rules.lines() {
        let words = line.split_ascii_whitespace().collect::<Vec<_>>();
        let [command, chain, rest @ ..] = words.as_slice() else {
            continue;
        };
        let parent = PARENTS.iter().position(|v| v == chain);
        if *command == "-N" && rest.is_empty() {
            if let Some(i) = parent {
                declared[i] = true;
            }
            continue;
        }
        if *command != "-A" {
            continue;
        }
        if let Some(i) = parent {
            jumps[i].get_or_insert(rest == ["-j", BYPASS]);
        } else if line.contains("NFQUEUE") || rest.contains(&"QUEUE") {
            // A queue in a different chain may receive unprotected traffic.
            return false;
        }
        if *chain != BYPASS || outgoing && incoming {
            continue;
        }
        let Some(matches) = rest.strip_suffix(&["-j", "ACCEPT"]) else {
            return false;
        };
        outgoing |= exact(matches, ep, false);
        incoming |= exact(matches, ep, true);
    }
    declared == [true, true] && jumps == [Some(true), Some(true)] && incoming && outgoing
}
#[cfg(test)]
mod tests {
    #[test]
    fn only_exact_router_owned_destination_uses_verified_wan_socket_mark() {
        let ip = "203.0.113.17".parse().unwrap();
        let run = |target: &str, via: &str, protected: bool| {
            super::direct_socket_mark(ip, &["wan0".into()], "ip", false, |_, args| {
                Ok(match args {
                    ["-4", "route", "get", _] => "203.0.113.17 dev awg2".into(),
                    ["-o", "-4", "rule", "show"] if protected => {
                        "68: from all fwmark 0/0x20000000 lookup 17842".into()
                    }
                    ["-o", "-4", "rule", "show"] => "68: from all lookup 17842".into(),
                    ["-o", "-4", "route", "show", "table", "17842", "match", _] => {
                        format!("{target} dev awg2 proto 242")
                    }
                    ["-4", "route", "get", _, "mark", "0x20000000"] => {
                        format!("203.0.113.17 dev {via}")
                    }
                    _ => panic!("unrecognized probe"),
                })
            })
        };
        assert_eq!(
            run("203.0.113.17", "wan0", true).unwrap(),
            Some(crate::DIRECT_SOCKET_MARK)
        );
        assert!(run("203.0.113.0/24", "wan0", true).is_err());
        assert!(run("203.0.113.17", "awg2", true).is_err());
        assert!(run("203.0.113.17", "wan0", false).is_err());
    }
    use super::*;
    #[test]
    fn group_classifier_only_marks_awg_socket_on_the_existing_valid_wan() {
        let rule="-A OUTPUT -m mark --mark 0x0/0x20000000 -m mark ! --mark 0x8000d500/0x8000ff80 -m set --match-set n2srt4_g0123456789abcdefabcdef dst -m comment --comment \"n2s-awg-setroute\" -j";
        let rows = format!("{rule} MARK --set-xmark 0x10100000/0x1ff00000\n{rule} ACCEPT");
        assert!(grouped_output(&rows, true).unwrap());
        let scoped = rows
            .replace(
                "-m set",
                "-m set --match-set n2srt4_g1111111111111111111111 src -m set",
            )
            .replace("0x10100000", "0x10000000");
        assert!(grouped_output(&scoped, true).unwrap());
        assert!(grouped_output(&scoped.replace("n2srt4_g111", "n2srt6_g111"), true).is_err());
        assert!(grouped_output(&scoped.replace(" src ", " dst "), true).is_err());
        assert!(grouped_output(&rows, false).is_err());
        assert!(grouped_output(&rows.replace("0x20000000", "0x40000000"), true).is_err());
        assert!(grouped_output(&rows.replace(" ACCEPT", " RETURN"), true).is_err());
        assert!(!grouped_output("-A OUTPUT -j STOCK", true).unwrap());
        let endpoint = "203.0.113.21".parse().unwrap();
        let check = |wan| {
            direct_socket_mark(endpoint, &["wan0".into()], "ip", true, |_, a| {
                Ok(match a {
                    ["-4", "route", "get", _] => "203.0.113.21 dev wan0".into(),
                    ["-4", "route", "get", _, "mark", "0x20000000"] => {
                        format!("203.0.113.21 dev {wan}")
                    }
                    _ => panic!("unknown transport lookup"),
                })
            })
        };
        assert_eq!(check("wan0").unwrap(), Some(crate::DIRECT_SOCKET_MARK));
        assert!(check("awg0").is_err());
    }
    #[test]
    fn netifd_uses_the_routed_l3_uplink_for_each_family() {
        let snapshot = r#"{"interface":[
            {"interface":"wan","up":true,"l3_device":"pppoe-wan","device":"eth0.2","route":[{"target":"0.0.0.0","mask":0}]},
            {"interface":"wan6","up":true,"l3_device":"wan.6","route":[{"target":"::","mask":0}]},
            {"up":true,"l3_device":"guest","route":[{"target":"0.0.0.0","mask":0,"table":100}]},
            {"up":false,"l3_device":"stale","route":[{"target":"0.0.0.0","mask":0}]},
            {"up":true,"l3_device":"br-lan","route":[{"target":"192.168.1.0","mask":24}]},
            {"up":true,"l3_device":"awg0","route":[{"target":"0.0.0.0","mask":0}]}
        ]}"#;
        let v4 = "198.51.100.1".parse().unwrap();
        let v6 = "2001:db8::1".parse().unwrap();
        assert!(netifd_wan(snapshot, "pppoe-wan", v4).unwrap());
        for table in ["254", r#""254""#, r#""main""#] {
            assert!(netifd_wan(
                &snapshot.replace(r#""table":100"#, &format!(r#""table":{table}"#)),
                "guest",
                v4
            )
            .unwrap());
        }
        assert!(netifd_wan(snapshot, "wan.6", v6).unwrap());
        for bad in [
            "eth0.2", "wan.6", "stale", "guest", "br-lan", "awg0", "lo", "",
        ] {
            assert!(!netifd_wan(snapshot, bad, v4).unwrap());
        }
        assert!(netifd_wan("{}", "pppoe-wan", v4).is_err());
    }
    #[test]
    fn native_and_mixed_openwrt_firewalls_require_complete_live_inventory() {
        let ep = "[2001:db8::1]:51820".parse().unwrap();
        for proc in [Ok(String::new()), Err(io::ErrorKind::NotFound.into())] {
            verify(ep, proc, true, |bin, args| {
                assert_eq!((bin, args), ("nft", ["list", "ruleset"].as_slice()));
                Ok("table inet fw4 { }".into())
            })
            .unwrap();
        }
        for reply in [
            Ok("queue num 8".into()),
            Err(io::ErrorKind::PermissionDenied.into()),
        ] {
            let mut reply = Some(reply);
            assert!(verify(ep, Ok(String::new()), true, |_, _| reply.take().unwrap()).is_err());
        }
        for table in ["filter", "mangle"] {
            assert!(verify(ep, Ok(table.into()), true, |bin, _| match bin {
                "nft" => Ok(String::new()),
                "ip6tables" => Err(io::ErrorKind::NotFound.into()),
                _ => unreachable!(),
            })
            .is_err());
        }
    }
    const BODY:&str="-N nfqws_post\n-N nfqws_pre\n-N nfqws2_bypass\n-A nfqws_pre -j nfqws2_bypass\n-A nfqws_post -j nfqws2_bypass\n-A nfqws_post -p udp -j NFQUEUE --queue-num 200\n-A nfqws2_bypass -d 192.0.2.4/32 -p udp -m udp --dport 500 -j ACCEPT\n-A nfqws2_bypass -p udp -s 192.0.2.4 --sport 500 -j ACCEPT";
    #[test]
    fn requires_exact_bidirectional_transport_and_both_first_jumps() {
        assert!(classified(BODY));
        assert!(!classified("-P FORWARD DROP\n-A INPUT -i lo -j ACCEPT"));
        let ep = "192.0.2.4:500".parse().unwrap();
        assert!(protects(BODY, ep));
        assert!(protects(
            &BODY
                .replace("192.0.2.4", "2001:db8::ab")
                .replace("/32", "/128"),
            "[2001:db8::ab]:500".parse().unwrap()
        ));
        for altered in [
            BODY.replace("--sport 500", "--sport 501"),
            BODY.replace("/32", "/24"),
            BODY.replace("-p udp -s", "-i eth0 -p udp -s"),
            BODY.replace("-N nfqws_pre", "-N missing"),
            BODY.replace(
                "-A nfqws_pre -j nfqws2_bypass",
                "-A nfqws_pre -j RETURN\n-A nfqws_pre -j nfqws2_bypass",
            ),
            BODY.replace("-d 192.0.2.4", "! -d 192.0.2.4"),
            BODY.replace("-j ACCEPT\n", "-j RETURN\n"),
            format!("{BODY}\n-A OUTPUT -j NFQUEUE"),
            format!("{BODY}\n-N AWG2_MARK"),
            BODY.replace(
                "-A nfqws2_bypass -p udp",
                "-A nfqws2_bypass -m comment --comment \"-p udp\"",
            ),
        ] {
            assert!(!protects(&altered, ep));
        }
    }
}
